namespace App\Enum;

/**
 * How the CSAF import last handled one document of a provider's feed (issue #319, ledger).
 *
 * - Processed: downloaded, parsed and handed to the upserter (whether it matched or not).
 * - Rebuild: downloaded, but only regenerated by the provider without a content change (#98).
 * - Skipped: downloaded, but deliberately not imported (not final, below the minimum severity).
 * - Failed: download or parse failed; retried until the attempt limit is reached.
 */
enum CsafDocumentOutcome: string
{
    case Processed = 'processed';
    case Rebuild = 'rebuild';
    case Skipped = 'skipped';
    case Failed = 'failed';

    public function label(): string
    {
        return match ($this) {
            self::Processed => 'Processed',
            self::Rebuild => 'Rebuild only',
            self::Skipped => 'Skipped',
            self::Failed => 'Failed',
        };
    }

    public function color(): string
    {
        return match ($this) {
            self::Processed => 'success',
            self::Rebuild, self::Skipped => 'secondary',
            self::Failed => 'danger',
        };
    }
}
